import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_gemv_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// One block per row of A. Each block computes dot(A[row,:], B[:]) using
// vectorized (float4) loads via CUTE tensors + recast, followed by a
// warp-shuffle + shared-memory tree reduction.
__global__ void gemv_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int64_t M, int64_t K)
{
    int64_t row = blockIdx.x;
    if (row >= M) return;
    int tid = threadIdx.x;
    int blockSize = blockDim.x;
    // Build CUTE tensors over global memory for this row of A and for B,
    // using a manually 64-bit-offset pointer to avoid ever materializing
    // the full (M,K) tensor (whose size/cosize computation would overflow
    // 32-bit indexing when M*K is large, e.g. M*K == 2^31).
    const float* rowPtr = A + row * K;
    Tensor rowA = make_tensor(make_gmem_ptr(rowPtr), make_shape(K), make_stride(Int<1>{}));
    Tensor mB   = make_tensor(make_gmem_ptr(B),       make_shape(K), make_stride(Int<1>{}));
    float sum = 0.0f;
    // Vectorized part: reinterpret contiguous chunks as float4.
    int64_t K4 = K / 4;
    if (K4 > 0) {
        Tensor rowA4 = recast<float4>(rowA);   // shape (K4)
        Tensor mB4   = recast<float4>(mB);     // shape (K4)
        for (int64_t i = tid; i < K4; i += blockSize) {
            float4 a = rowA4(i);
            float4 b = mB4(i);
            sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
        }
    }
    // Remainder (K not divisible by 4)
    int64_t rem_start = K4 * 4;
    for (int64_t i = rem_start + tid; i < K; i += blockSize) {
        sum += rowA(i) * mB(i);
    }
    // ---- Intra-warp reduction ----
    unsigned mask = 0xffffffffu;
    int lane = tid & 31;
    int warpId = tid >> 5;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
    }
    // ---- Inter-warp reduction via shared memory ----
    __shared__ float warpSums[32]; // supports up to 1024 threads/block
    int numWarps = (blockSize + 31) >> 5;
    if (lane == 0) {
        warpSums[warpId] = sum;
    }
    __syncthreads();
    if (warpId == 0) {
        float v = (lane < numWarps) ? warpSums[lane] : 0.0f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            v += __shfl_down_sync(mask, v, offset);
        }
        if (lane == 0) {
            C[row] = v;
        }
    }
}

torch::Tensor cute_gemv_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();

    int64_t M = A_c.size(0);
    int64_t K = A_c.size(1);

    auto C = torch::empty({M, 1}, A.options());

    const float* ptrA = A_c.data_ptr<float>();
    const float* ptrB = B_c.data_ptr<float>();
    float* ptrC = C.data_ptr<float>();

    int threads = 256;
    dim3 block(threads);
    dim3 grid((unsigned int)M);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    gemv_kernel<<<grid, block, 0, stream>>>(ptrA, ptrB, ptrC, M, K);

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "gemv_kernel launch failed: ", cudaGetErrorString(err));

    return C;
}
"""

cute_gemv_ext = load_inline(
    name="cute_gemv_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_gemv_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CUTE-based CUDA kernel. One block per output row, vectorized (float4)
    reduction over K using CUTE tensors, followed by warp-shuffle reduction.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemv_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_gemv_forward(A, B)

