    float sum = 0.0f;

    // Vectorized part: reinterpret contiguous chunks as float4.
    int K4 = K / 4;
    if (K4 > 0) {
        Tensor rowA4 = recast<float4>(rowA);   // shape (K4)
        Tensor mB4   = recast<float4>(mB);     // shape (K4)

