            float4 a = rowA4(i);
            float4 b = mB4(i);
            sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
        }
    }

    // Remainder (K not divisible by 4)
    int rem_start = K4 * 4;
    for (int i = rem_start + tid; i < K; i += blockSize) {
        sum += rowA(i) * mB(i);
    }

