    __shared__ float warpSums[32];
    int lane = tid & 31;
    int warpId = tid >> 5;
    if (lane == 0) {
        warpSums[warpId] = sum;
    }
    __syncthreads();

    int numWarps = (blockSize + 31) / 32;
    if (warpId == 0) {
        float v = (lane < numWarps) ? warpSums[lane] : 0.0f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            v += __shfl_down_sync(mask, v, offset);
        }
        if (lane == 0) {
            C[row] = v;
        }
    }
