class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented as a hand-authored
    PTX kernel launched through cutegen.ptx_runtime.PtxModule. One CUDA
    block per output row; each block performs a vectorized (float4) dot
    product reduction over K, followed by warp-shuffle + shared-memory
    tree reduction, mirroring the original CuTe/CUDA kernel.
    """

    def __init__(self):
        super().__init__()
        self._module = None
        self._threads = 256

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "A and B must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, \
            "Expect float32 tensors"
        assert A.dim() == 2, "A must be 2D (M, K)"
        assert B.dim() == 2 and B.size(1) == 1, "B must be (K, 1)"
        assert A.size(1) == B.size(0), "Inner dimensions must match"

        A_c = A.contiguous()
        B_c = B.contiguous()

        M, K = A_c.shape
        C = torch.empty((M, 1), device=A.device, dtype=torch.float32)

        module = self._module if self._module is not None else _get_module()
        self._module = module

        stream = torch.cuda.current_stream().cuda_stream

        threads = self._threads
        grid = (int(M), 1, 1)
        block = (threads, 1, 1)

        module.launch(
            "gemv_kernel",
            grid=grid,
            block=block,
            shared_mem_bytes=0,
            stream=stream,
            args=[
                u64(A_c.data_ptr()),
                u64(B_c.data_ptr()),
                u64(C.data_ptr()),
                i64(M),
                i64(K),
            ],
        )

        return C
